export type CertificateData = {
  recipientName: string;
  courseName: string;
  issuedDateFormatted: string;
  credentialId: string;
};

const FOUNDERS = [
  { name: "Aishwarya Srinivasan", title: "Co-Founder" },
  { name: "Arvind Narayanamurthy", title: "Co-Founder" },
];

// Matches the approved Canva source ("TGA Mastering Agentic AI Certification
// Final") — single design, no light/dark variants. Ink (#1c2120) and gold
// (#96631d) are the two colors actually used throughout the source file —
// pulled from a read-only inspection of the design's own text elements
// (font/color/opacity), not eyeballed off a screenshot. There's no separate
// muted-gray color anywhere; secondary lines (founder title/org) are just
// ink at 80% opacity, applied directly on .signature-title below.
const COLORS = {
  outerMargin: "#F5EFE5",
  background: "linear-gradient(135deg, #FEFEFE 0%, #FCFCFB 50%, #FAFAF9 100%)",
  border: "#C9A227",
  ink: "#1c2120",
  gold: "#96631d",
};

// The full brand lockup (icon + divider + "THE GEN ACADEMY" wordmark) is
// one flattened image in the source design (no separate text layer) --
// cropped directly from the Canva export rather than approximated.
const BRAND_LOCKUP_DATA_URL = "data:image/png;base64,";

// The actual signature font from the Canva source ("Amsterdam Four") — a
// paid marketplace font, not on Google Fonts, so it's embedded directly
// rather than loaded over the network (also avoids depending on Google
// Fonts being reachable from the serverless Chromium render at all).
const FONT_AMSTERDAM_DATA_URL = "data:font/ttf;base64,";

// The course-name display font from the source ("Lovelo") — also a paid
// font, embedded the same way as Amsterdam Four above. Canva referenced
// the plain "Lovelo" family (not the outlined "Lovelo Line" variants),
// which corresponds to the solid "Lovelo Black" weight — the only solid
// (non-outlined) style the family ships.
const FONT_LOVELO_DATA_URL = "data:font/otf;base64,";

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function calendarIcon(color: string, size: number): string {
  return `
  <svg width="${size}" height="${size}" viewBox="0 0 30 30" fill="none" xmlns="http://www.w3.org/2000/svg">
    <g stroke="${color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
      <rect x="3" y="6" width="24" height="21" rx="2.5" />
      <line x1="3" y1="12" x2="27" y2="12" />
      <line x1="9" y1="2.5" x2="9" y2="8" />
      <line x1="21" y1="2.5" x2="21" y2="8" />
    </g>
  </svg>`;
}

function idIcon(color: string, size: number): string {
  return `
  <svg width="${size}" height="${size}" viewBox="0 0 30 30" fill="none" xmlns="http://www.w3.org/2000/svg">
    <g stroke="${color}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
      <path d="M15 2 4 6.5v7c0 8 5 12.5 11 14.5 6-2 11-6.5 11-14.5v-7L15 2z" />
      <circle cx="15" cy="13.5" r="3.2" />
      <path d="M9.5 20.5c1.4-2.6 3.4-3.8 5.5-3.8s4.1 1.2 5.5 3.8" />
    </g>
  </svg>`;
}

// Every position/size/font-size/letter-spacing/weight below was measured
// from a PPTX export of the source design (python-pptx gives exact EMU
// positions and point sizes, unlike the PNG-pixel-guessing and the Canva
// CDF read used earlier — the CDF's coordinate system didn't correspond
// to the page dimensions in any way that could be reverse-engineered
// reliably). Converted from the source's 11in x 8.5in page to this
// template's 1600x1000 canvas using independent x/y scale factors
// (sx=1600/11, sy=1000/8.5) — the two aspect ratios differ, so positions
// are matched as a fraction of each axis rather than a single uniform
// scale. Absolute-positioned throughout rather than flexbox-flowed, since
// that's the only way to reproduce exact source spacing instead of an
// approximation of it.
export function buildCertificateHtml(data: CertificateData): string {
  const recipientName = escapeHtml(data.recipientName);
  const courseName = escapeHtml(data.courseName);
  const issuedDateFormatted = escapeHtml(data.issuedDateFormatted);
  const credentialId = escapeHtml(data.credentialId);
  const p = COLORS;

  // Amsterdam Four's glyphs sit ~10px left of center within their own layout
  // box (measured on both founder names, so it's the font's side-bearing,
  // not something specific to either name) — shifted right to compensate,
  // otherwise the script visibly leans left of the underline beneath it.
  const signatureBlock = (name: string, title: string, centerX: number) => `
    <div class="el signature-script" style="left:${centerX - 160}px;top:756px;width:340px;height:44px;">${escapeHtml(name)}</div>
    <div class="sig-line" style="left:${centerX - 172}px;top:819px;width:345px;"></div>
    <div class="el signature-name" style="left:${centerX - 140}px;top:853px;width:280px;height:24px;">${escapeHtml(name.toUpperCase())}</div>
    <div class="el signature-title" style="left:${centerX - 95}px;top:881px;width:190px;height:48px;">${escapeHtml(title.toUpperCase())}<br/>THE GEN ACADEMY</div>`;

  // Group-child positions in the source PPTX are in a scaled inner
  // coordinate space (chOff/chExt on the group's transform) distinct from
  // the group's own outer position — missed that on the first pass here,
  // which is why signatures overflowed the canvas. Centers below are
  // correct once that 0.75x child-space scale is applied.
  const signatures = [
    // Column 1 runs from the metadata|sig1 divider (612) to the sig1|sig2
    // divider (988) — true center 800, not 790. Column 2 mirrors the same
    // 376px width from 988, center 1176, which is what was already here —
    // Aishwarya's was the one out of step with her own column.
    signatureBlock(FOUNDERS[0].name, FOUNDERS[0].title, 800),
    signatureBlock(FOUNDERS[1].name, FOUNDERS[1].title, 1176),
  ].join("");

  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<link rel="preconnect" href="https://fonts.googleapis.com" />
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
<link
  href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Poppins:wght@400;500;600;700;800&display=swap"
  rel="stylesheet"
/>
<style>
  @font-face {
    font-family: "Amsterdam Four";
    src: url(${FONT_AMSTERDAM_DATA_URL}) format("truetype");
    font-weight: normal;
    font-style: normal;
  }

  @font-face {
    font-family: "Lovelo";
    src: url(${FONT_LOVELO_DATA_URL}) format("opentype");
    font-weight: normal;
    font-style: normal;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body { width: 1600px; height: 1000px; }

  .certificate {
    width: 1600px;
    height: 1000px;
    position: relative;
    background: ${p.outerMargin};
    font-family: "Poppins", Helvetica, Arial, sans-serif;
    overflow: hidden;
  }

  /* The source has two background tones, not one: a cream margin outside
     the frame, near-white inside it. Sampled directly from the export —
     x=0 reads #F5EFE5, x=300+ (inside the frame) reads ~#FEFEFE — rather
     than the single warm-cream gradient across the whole card I had
     before, which read as uniformly off-white. */
  .inner-panel {
    position: absolute;
    left: 34px;
    top: 34px;
    width: 1532px;
    height: 932px;
    background: ${p.background};
  }

  .el {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: ${p.ink};
  }

  /* Right-triangle paper-fold accent, top-right — exact bounding box from
     the source (Freeform 3); the actual asset is a picture-fill rectangle
     (its vector path is a plain rect), so the diagonal look is baked into
     that image's own gradient, not a real clipped vector edge. This
     clip-path is an approximation of that baked-in look. */
  .bg-wedge {
    position: absolute;
    left: 1175px;
    top: 14px;
    width: 417px;
    height: 351px;
    background: linear-gradient(135deg, rgba(120,120,130,0.16), rgba(120,120,130,0.02) 75%);
    clip-path: polygon(100% 0, 100% 100%, 0 0);
  }

  /* Left wedge (Freeform 4) — same width as the top-right one (confirmed
     same source asset reused), but much taller: it runs from 33% down to
     97% down the page, i.e. almost to the bottom edge. */
  .bg-wedge-left {
    position: absolute;
    left: 9px;
    top: 328px;
    width: 417px;
    height: 646px;
    background: linear-gradient(-45deg, rgba(120,120,130,0.14), rgba(120,120,130,0.02) 70%);
    clip-path: polygon(0 0, 0 100%, 100% 100%);
  }

  .bg-mesh {
    position: absolute;
    inset: 0;
    opacity: 0.5;
    background-image:
      repeating-linear-gradient(0deg, rgba(180,150,80,0.07) 0px, rgba(180,150,80,0.07) 1px, transparent 1px, transparent 133px),
      repeating-linear-gradient(60deg, rgba(180,150,80,0.07) 0px, rgba(180,150,80,0.07) 1px, transparent 1px, transparent 230px),
      repeating-linear-gradient(-60deg, rgba(180,150,80,0.07) 0px, rgba(180,150,80,0.07) 1px, transparent 1px, transparent 230px);
  }

  /* Frame corners are cut at 45° (an octagon) — an SVG polygon so the
     chamfer actually renders as a stroked line, which a CSS clip-path on
     a bordered box would not do. Inset is genuinely equidistant on all
     four sides — confirmed by scanning the export for the border's pixel
     position rather than trusting the picture-fill asset's bounding box,
     which includes internal padding and isn't a reliable proxy for where
     the visible line actually sits. */
  .frame-svg {
    position: absolute;
    left: 34px;
    top: 34px;
    width: 1532px;
    height: 932px;
    overflow: visible;
  }

  .diamond {
    position: absolute;
    background: ${p.border};
    transform: translateX(-50%) rotate(45deg);
  }

  .brand-lockup {
    position: absolute;
    left: 50%;
    top: 58px;
    height: 85px;
    width: auto;
    transform: translateX(-50%);
    display: block;
  }

  .divider-line { position: absolute; height: 1.5px; background: ${p.border}; }

  .headline {
    left: 388px; top: 148px; width: 800px; height: 109px;
    font-family: "Cormorant Garamond", Georgia, serif;
    font-size: 81px;
    font-weight: 700;
    letter-spacing: 0.15em;
  }

  .subhead {
    left: 578px; top: 252px; width: 454px; height: 40px;
    font-size: 28px;
    letter-spacing: 0.4em;
    font-weight: 500;
    text-transform: uppercase;
    color: ${p.gold};
  }

  .awarded-label {
    left: 560px; top: 352px; width: 484px; height: 27px;
    font-size: 20px;
    letter-spacing: 0.2em;
    font-weight: 400;
    text-transform: uppercase;
  }

  /* Fixed top+height (matching the source's single-line "Jane Doe" box)
     breaks for a long recipient name that wraps to 2+ lines — it would
     overflow into the headline above and the divider below. top here is
     the box's vertical CENTER (not its top edge) with height:auto, so
     wrapping grows the box symmetrically instead of only downward. */
  /* left:50%/translateX(-50%) instead of a fixed left+width, so the
     render-time expand-to-fit step (certificate-render.ts) can grow this
     box wider for a long name and have it stay centered automatically,
     rather than needing to recompute left every time it resizes.
     top-anchored (not vertically centered) — growing downward toward the
     divider at 532px leaves ~149px of headroom for a 2nd line, versus only
     ~52px if centered symmetrically around the old single-line midpoint,
     which is too little room and collides with "THIS IS PROUDLY AWARDED
     TO" above before a 2nd line ever gets used. */
  .recipient-name {
    left: 50%; top: 375px; width: 460px; height: auto;
    transform: translateX(-50%);
    font-family: "Cormorant Garamond", Georgia, serif;
    font-size: 97px;
    font-weight: 600;
    letter-spacing: 0.02em;
    line-height: 1.15;
    color: ${p.gold};
  }

  .completion-label {
    left: 532px; top: 550px; width: 541px; height: 26px;
    font-size: 18px;
    letter-spacing: 0.05em;
    font-weight: 400;
  }

  /* "Lovelo" in the source — a paid display font, not on Google Fonts and
     not yet embedded (unlike Amsterdam Four, I don't have this file).
     Poppins ExtraBold below is a placeholder, not a confirmed match. */
  /* Same reasoning as .recipient-name: a long course title needs to wrap
     without colliding with "for successfully..." above or "conducted
     by..." below. */
  .course-name {
    left: 50%; top: 598px; width: 716px; height: auto;
    transform: translateX(-50%);
    font-family: "Lovelo", "Poppins", Helvetica, Arial, sans-serif;
    font-size: 46px;
    font-weight: normal;
    letter-spacing: 0.05em;
    line-height: 1.2;
    text-transform: uppercase;
  }

  .conducted-label {
    left: 613px; top: 657px; width: 384px; height: 25px;
    font-size: 17px;
    letter-spacing: 0.05em;
    font-weight: 400;
  }

  .metadata-label {
    justify-content: flex-start;
    font-size: 14px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
  }

  /* The source has these as plain Poppins regular (bold=None), not bold —
     confirmed from the PPTX text-run data, not a visual guess. */
  .metadata-value {
    justify-content: flex-start;
    font-size: 17px;
    font-weight: 400;
    color: ${p.gold};
  }

  /* Both icons are the same size now (unified per earlier feedback), so
     they need the same offset from their label to look aligned — the
     shield icon was sitting 9px closer to its label than the calendar
     icon was to its own, which read as uneven spacing between the rows. */
  /* Re-measured directly off the source PNG's pixel bands (row-scanning
     for gold/dark ink) rather than trusting the PPTX-derived numbers here
     — those two disagreed by ~15px, and the pixel scan is a direct read
     of what's actually on screen, not a converted assumption. */
  /* Measured actual ink bounds vs the label+value text block on both rows:
     both icons sat ~10-11px above the text block's vertical center,
     consistently — shifted down to match. */
  .icon-cal { position: absolute; left: 245px; top: 755px; }
  .icon-id { position: absolute; left: 245px; top: 853px; }

  .signature-script {
    font-family: "Amsterdam Four", cursive;
    font-size: 28px;
    font-weight: 400;
    white-space: nowrap;
  }

  .sig-line { position: absolute; height: 1.5px; background: ${p.border}; }

  .signature-name {
    font-size: 15px;
    font-weight: 700;
    letter-spacing: 0.05em;
    color: ${p.gold};
  }

  .signature-title {
    font-size: 15px;
    letter-spacing: 0.05em;
    line-height: 1.5;
    opacity: 0.8;
  }

  .sig-divider {
    position: absolute;
    width: 1px;
    background: rgba(150,150,150,0.35);
  }
</style>
</head>
<body>
  <section class="certificate">
    <div class="inner-panel"></div>
    <div class="bg-wedge"></div>
    <div class="bg-wedge-left"></div>
    <div class="bg-mesh"></div>
    <svg class="frame-svg" preserveAspectRatio="none" viewBox="0 0 1532 932">
      <polygon
        points="36,0 1496,0 1532,36 1532,896 1496,932 36,932 0,896 0,36"
        fill="none"
        stroke="${p.border}"
        stroke-width="1.5"
      />
    </svg>

    <img class="brand-lockup" src="${BRAND_LOCKUP_DATA_URL}" alt="The Gen Academy" />

    <div class="el headline">CERTIFICATE</div>
    <div class="el subhead">OF COMPLETION</div>
    <div class="divider-line" style="left:364px;top:278px;width:190px;"></div>
    <div class="divider-line" style="left:1046px;top:278px;width:190px;"></div>
    <div class="divider-line" style="left:686px;top:313px;width:100px;"></div>
    <div class="diamond" style="left:809px;top:308px;width:11px;height:11px;"></div>
    <div class="divider-line" style="left:833px;top:313px;width:100px;"></div>

    <div class="el awarded-label">THIS IS PROUDLY AWARDED TO</div>
    <div class="el recipient-name">${recipientName}</div>
    <div class="divider-line" style="left:426px;top:532px;width:344px;"></div>
    <div class="diamond" style="left:802px;top:527px;width:10px;height:10px;"></div>
    <div class="divider-line" style="left:826px;top:532px;width:352px;"></div>

    <div class="el completion-label">for successfully completing the masterclass</div>
    <div class="el course-name">${courseName}</div>
    <div class="el conducted-label">conducted by The Gen Academy.</div>

    <div class="icon-cal">${calendarIcon(p.gold, 46)}</div>
    <div class="el metadata-label" style="left:336px;top:750px;width:195px;height:19px;">Date of Completion</div>
    <div class="el metadata-value" style="left:336px;top:778px;width:143px;height:23px;">${issuedDateFormatted}</div>
    <div class="divider-line" style="left:245px;top:819px;width:338px;"></div>
    <div class="icon-id">${idIcon(p.gold, 46)}</div>
    <div class="el metadata-label" style="left:336px;top:851px;width:130px;height:19px;">Certificate ID</div>
    <div class="el metadata-value" style="left:336px;top:879px;width:252px;height:23px;">${credentialId}</div>

    <div class="sig-divider" style="left:612px;top:730px;height:204px;"></div>
    <div class="sig-divider" style="left:988px;top:730px;height:204px;"></div>
    ${signatures}
  </section>
</body>
</html>`;
}
